        testThreeMatrices();
        testFourMatrices();
        testNullArray();
        testNullElementInChain();
        testEmptyChain();
        testIncompatibleChain();
        testArgumentParsing();
        testArgumentParsingInvalid();
        System.out.println("All tests passed!");
    }
}

